import { CommonModule } from '@angular/common';
import { Component, inject } from '@angular/core';
import { NavigationEnd, Router, RouterModule } from '@angular/router';
import {
  IonContent,
  IonHeader,
  IonItem,
  IonLabel,
  IonList,
  IonMenu,
  IonMenuToggle,
  IonRouterLink,
  IonRouterOutlet,
  IonText,
  IonToolbar,
} from '@ionic/angular/standalone';
import { filter, map, startWith } from 'rxjs';
import {
  accountRoutePath,
  getRoutePath,
  loginRoutePath,
  profileRoutePath,
  toolsRoutePath,
  settingsRoutePath,
} from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { AuthService } from '../common/auth/auth.service';
import { CapacitorService } from '../common/capacitor/capacitor.service';
import { MenuToggleComponent } from '../common/menu/menu-toggle.component';
import { MenuService } from '../common/menu/menu.service';
import { ProfileService } from '../profile/profile.service';
import { FooterComponent } from './footer/footer.component';
@Component({
  selector: 'app-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  imports: [
    IonLabel,
    IonToolbar,
    IonList,
    IonContent,
    IonItem,
    IonText,
    IonMenu,
    IonMenuToggle,
    IonHeader,
    IonRouterOutlet,
    CommonModule,
    FooterComponent,
    IonRouterLink,
    RouterModule,
    MenuToggleComponent,
  ],
})
export class LayoutComponent {
  readonly alertService = inject(AlertService);
  readonly authService = inject(AuthService);
  readonly capacitorService = inject(CapacitorService);
  readonly menuService = inject(MenuService);
  readonly profileService = inject(ProfileService);
  readonly router = inject(Router);

  readonly alertButtons = [
    {
      text: 'Cancel',
      role: 'cancel',
    },
    {
      text: 'Log Out',
      role: 'confirm',
      handler: () => this.signOut(),
    },
  ];

  menuOpen$ = this.menuService.open$;

  accountRouterLink$ = this.router.events.pipe(
    filter((e) => e instanceof NavigationEnd),
    map((route) => route.url),
    map((basePath) => [basePath, accountRoutePath]),
    startWith([accountRoutePath])
  );

  profileRouterLink$ = this.router.events.pipe(
    filter((e) => e instanceof NavigationEnd),
    map((route) => route.url),
    map((basePath) => [basePath, profileRoutePath]),
    startWith([profileRoutePath])
  );

  toolsRouterLink$ = this.router.events.pipe(
    filter((e) => e instanceof NavigationEnd),
    map((route) => route.url),
    map((basePath) => [basePath, toolsRoutePath]),
    startWith([toolsRoutePath])
  );

  settingsRouterLink$ = this.router.events.pipe(
    filter((e) => e instanceof NavigationEnd),
    map((route) => route.url),
    map((basePath) => [basePath, settingsRoutePath]),
    startWith([settingsRoutePath])
  );

  isAdmin$ = this.profileService.isAdmin$;

  get isIos(): boolean {
    return this.capacitorService.ios;
  }

  onIonWillOpen() {
    this.menuService.setOpen(true);
  }

  onIonWillClose() {
    this.menuService.setOpen(false);
  }

  async signOut() {
    const alert = await this.alertService.createConfirm({
      header: 'Are you sure?',
      message: 'You will be logged out of your account.',
      confirmButtonText: 'Log Out',
    });

    const result = await alert.onDidDismiss();

    if (result.role !== 'confirm') {
      return;
    }

    await this.authService.signOut();
    await this.router.navigate([getRoutePath(loginRoutePath)], {
      replaceUrl: true,
    });
  }
}
